package com.bank.reg.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Counts contiguous stretches whose net total lies within [lower, upper].
public class RangeSumCounter {
    private static final Logger log = Logger.getLogger(RangeSumCounter.class.getName());

    public int countStretchesInBand(int[] flows, long lower, long upper) {
        if (flows == null || flows.length == 0) {
            return 0;
        }
        int n = flows.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + flows[i];
        }
        int total = mergeCount(prefix, 0, n + 1, lower, upper, new long[n + 1]);
        final int result = total;
        log.info(() -> "Stretches with net in [" + lower + ", " + upper + "] over "
                + Arrays.toString(flows) + " = " + result);
        return total;
    }

    // Sort prefix[lo, hi) while counting qualifying (left, right) prefix pairs.
    private int mergeCount(long[] prefix, int lo, int hi, long lower, long upper, long[] buf) {
        if (hi - lo <= 1) {
            return 0;
        }
        int mid = (lo + hi) >>> 1;
        int count = mergeCount(prefix, lo, mid, lower, upper, buf)
                + mergeCount(prefix, mid, hi, lower, upper, buf);

        // Count: for each right index r, left endpoints with prefix in [P[r]-upper, P[r]-lower].
        int low = lo, high = lo;
        for (int r = mid; r < hi; r++) {
            while (low < mid && prefix[low] < prefix[r] - upper) low++;
            while (high < mid && prefix[high] <= prefix[r] - lower) high++;
            count += high - low;
        }
        final int levelCount = count;
        log.fine(() -> "Merge [" + lo + "," + hi + ") running count = " + levelCount);

        // Standard merge to keep [lo, hi) sorted for the parent.
        int i = lo, j = mid, t = lo;
        while (i < mid && j < hi) {
            buf[t++] = (prefix[i] <= prefix[j]) ? prefix[i++] : prefix[j++];
        }
        while (i < mid) buf[t++] = prefix[i++];
        while (j < hi) buf[t++] = prefix[j++];
        System.arraycopy(buf, lo, prefix, lo, hi - lo);
        return count;
    }
}
